@Test
public void testServiceWithAdapterAndConsumer(BundleContext context) {
    DependencyManager m = new DependencyManager(context);
    // helper class that ensures certain steps get executed in sequence
    Ensure e = new Ensure();
    Component provider = m.createComponent().setInterface(OriginalService.class.getName(), null).setImplementation(new ServiceProvider(e));
    Component consumer = m.createComponent().setImplementation(new ServiceConsumer(e)).add(m.createServiceDependency().setService(AdaptedService.class).setRequired(true));
    Component adapter = m.createAdapterService(OriginalService.class, null).setInterface(AdaptedService.class.getName(), null).setImplementation(ServiceAdapter.class);
    // add the provider and the adapter
    m.add(provider);
    m.add(adapter);
    // add a consumer that will invoke the adapter
    // which will in turn invoke the original provider
    m.add(consumer);
    // now validate that both have been invoked in the right order
    e.waitForStep(2, 5000);
    // remove the provider again
    m.remove(provider);
    // ensure that the consumer is stopped
    e.waitForStep(3, 5000);
    // remove adapter and consumer
    m.remove(adapter);
    m.remove(consumer);
}

@Test
public void testAdapterWithAspectMultipleTimes(BundleContext context) {
    // TODO this test is broken, it assumes that the order in which listeners are added to the BundleContext will also
    // be the order in which they're invoked (which from a spec point of view is not true)
    DependencyManager m = new DependencyManager(context);
    // helper class that ensures certain steps get executed in sequence
    Ensure e = new Ensure();
    // create a service provider and consumer
    Component provider = m.createComponent().setImplementation(new ServiceProvider()).setInterface(OriginalService.class.getName(), null);
    Component consumer = m.createComponent().setImplementation(new ServiceConsumer(e)).add(m.createServiceDependency().setService(AdaptedService.class).setCallbacks("add", "remove"));
    Component adapter = m.createAdapterService(OriginalService.class, null).setInterface(AdaptedService.class.getName(), null).setImplementation(ServiceAdapter.class);
    Component adapter2 = m.createAdapterService(OriginalService.class, null).setInterface(AdaptedService.class.getName(), null).setImplementation(ServiceAdapter.class);
    Component aspect = m.createAspectService(OriginalService.class, null, 10, null).setImplementation(ServiceAspect.class);
    m.add(provider);
    int stepsInLoop = 10;
    int loops = 10;
    for (int loop = 0; loop < loops; loop++) {
        int offset = stepsInLoop * loop;
        m.add(adapter);
        m.add(consumer);
        e.waitForStep(1 + offset, 5000);
        m.add(aspect);
        // the aspect adapter will appear
        // the original adapter will disappear
        e.waitForStep(3 + offset, 5000);
        m.add(adapter2);
        // another aspect adapter will appear
        e.waitForStep(4 + offset, 5000);
        m.remove(provider);
        // two times:
        // the aspect adapter will disappear
        // the original adapter will (briefly) appear
        // the original adapter will disappear
        // TODO the test will fail somewhere here most of the time
        e.waitForStep(8 + offset, 5000);
        m.remove(consumer);
        // nothing should happen, all consumed services were already gone
        e.step(9 + offset);
        m.add(provider);
        // still nothing should happen
        e.step(10 + offset);
        m.remove(adapter);
        m.remove(adapter2);
        m.remove(aspect);
    }
    m.remove(provider);
    e.waitForStep(stepsInLoop * loops, 5000);
}

