@Test
public void test() {
    // wait for components to fire up in the background....
    delay();
    final Component[] components = getComponents();
    TestCase.assertNotNull(components);
    for (Component component : components) {
        TestCase.assertTrue("Expecting component " + component.getName() + " to be enabled", component.isDefaultEnabled());
        TestCase.assertEquals("Expecting component " + component.getName() + " to be active", Component.STATE_ACTIVE, component.getState());
        final Object instance = component.getComponentInstance().getInstance();
        TestCase.assertTrue("Expecting component " + component.getName() + " to be an AbstractActivateSignatureTestComponent", instance instanceof AbstractActivateSignatureTestComponent);
        final AbstractActivateSignatureTestComponent aastc = (AbstractActivateSignatureTestComponent) instance;
        TestCase.assertEquals("Expect activate method to be called", component.getName(), aastc.getMethodCalled());
    }
}

@Test
public void test_activator_not_declared() {
    final String componentname = "ActivatorComponent.no.decl";
    final Component component = findComponentByName(componentname);
    TestCase.assertNotNull(component);
    TestCase.assertFalse(component.isDefaultEnabled());
    TestCase.assertEquals(Component.STATE_DISABLED, component.getState());
    component.enable();
    delay();
    TestCase.assertEquals(Component.STATE_ACTIVE, component.getState());
    component.disable();
    delay();
    TestCase.assertEquals(Component.STATE_DISABLED, component.getState());
}

