    if (twoConfigs[0].getState() == Component.STATE_ACTIVE) {
        // [0] is active, [1] expected disabled
        activeConfig = 0;
        inactiveConfig = 1;
    } else if (twoConfigs[1].getState() == Component.STATE_ACTIVE) {
        // [1] is active, [0] expected disabled
        activeConfig = 1;
        inactiveConfig = 0;
